import"../../modulepreload-polyfill-YP0FEG5d.js";/* empty css                     *//* empty css                 */const e=document.getElementById("tweetUrl"),t=document.getElementById("btnAnalyze"),n=document.getElementById("resultArea"),i=document.getElementById("resultContent");t.addEventListener("click",()=>{const t=function(){const t=e.value.trim().match(/(?:twitter\.com|x\.com)\/[^\/]+\/status\/(\d+)/);return t?t[1]:null}();if(!t)return i.innerHTML='<p style="color: #FF5555;" data-i18n="tools.social.twitter-video.text.031">Invalid Twitter/X URL. Please check the format.</p>',void n.classList.add("show");i.innerHTML=`\n        <div class="tweet-info">\n          <div class="tweet-author">Tweet ID: <span style="color: #00D9FF;" data-i18n="tools.social.twitter-video.text.032">${t}</span></div>\n          <div class="tweet-text">Due to Twitter/X API restrictions, direct media extraction requires additional authentication.</div>\n        </div>\n        <div class="media-list">\n          <div class="media-item">\n            <span class="media-type" data-i18n="tools.social.twitter-video.text.033">Recommended Methods</span>\n          </div>\n          <div style="padding: 0.75rem; color: #A1A1AA; font-size: 0.875rem; line-height: 1.6;">\n            <strong>1. Browser Developer Tools:</strong><br>\n            - Open the tweet in your browser<br>\n            - Right-click and select "Inspect"<br>\n            - Go to Network tab<br>\n            - Play the video<br>\n            - Look for .mp4 files in the Network tab<br>\n            - Right-click the file → "Open in new tab" → Save<br><br>\n            \n            <strong>2. Browser Extensions:</strong><br>\n            - Install "Video DownloadHelper" or similar<br>\n            - Navigate to the tweet<br>\n            - Click the extension icon<br>\n            - Download the detected video<br><br>\n            \n            <strong>3. Mobile Method:</strong><br>\n            - Use the official Twitter/X app<br>\n            - Some videos have a "Share" → "Save" option<br>\n            - Or use your device's screen recording feature\n          </div>\n        </div>\n      `,n.classList.add("show")}),e.addEventListener("keypress",e=>{"Enter"===e.key&&t.click()});
